            const double clhs155 =     DeltaDOperator[2](1,1); // DERIVATIVE(DOPERATOR(1,1)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,0))
            const double clhs156 =     DeltaMOperator[2](1,1); // DERIVATIVE(MOPERATOR(1,1)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,0))
            const double clhs157 =     NormalSlave(1,0)*(-clhs153*clhs7 + clhs154*clhs3 + clhs155*clhs5 - clhs156*clhs8 + clhs6) + NormalSlave(1,1)*(clhs10*clhs154 + clhs11*clhs155 - clhs12*clhs153 - clhs13*clhs156);
            const double clhs158 =     NormalSlave(1,0)*clhs157;
