            const double clhs172 =     TangentFactor*(-clhs159 - clhs160 - clhs161 - clhs162 + clhs171 + clhs6) + clhs158;
            const double clhs173 =     DeltaMOperator[3](1,0); // DERIVATIVE(MOPERATOR(1,0)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,1))
            const double clhs174 =     DeltaDOperator[3](1,0); // DERIVATIVE(DOPERATOR(1,0)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,1))
            const double clhs175 =     DeltaDOperator[3](1,1); // DERIVATIVE(DOPERATOR(1,1)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,1))
            const double clhs176 =     DeltaMOperator[3](1,1); // DERIVATIVE(MOPERATOR(1,1)(U1(0,0), U1(0,1), U1(1,0), U1(1,1), U2(0,0), U2(0,1), U2(1,0), U2(1,1)), U1(1,1))
            const double clhs177 =     NormalSlave(1,0)*(-clhs173*clhs7 + clhs174*clhs3 + clhs175*clhs5 - clhs176*clhs8) + NormalSlave(1,1)*(clhs10*clhs174 + clhs11*clhs175 - clhs12*clhs173 - clhs13*clhs176 + clhs6);
