            rLocalLHS(7,2)+=DynamicFactor[1]*(clhs206*clhs228 - clhs227*clhs77);
            rLocalLHS(7,3)+=DynamicFactor[1]*(clhs209*clhs228 - clhs227*clhs97);
            rLocalLHS(7,4)+=DynamicFactor[1]*(-clhs116*clhs227 + clhs212*clhs228);
