            rLocalLHS(7,6)+=DynamicFactor[1]*(-clhs155*clhs227 + clhs218*clhs228);
            rLocalLHS(7,7)+=DynamicFactor[1]*(-clhs175*clhs227 + clhs221*clhs228);
            rLocalLHS(7,11)+=clhs229;
            rLocalLHS(10,0)+=ScaleFactor*(clhs230*clhs231 - clhs232*clhs233 + clhs37);
            rLocalLHS(10,1)+=ScaleFactor*(clhs231*clhs235 - clhs232*clhs234 + clhs61);
            rLocalLHS(10,2)+=ScaleFactor*(clhs231*clhs236 - clhs232*clhs237 + clhs81);
            rLocalLHS(10,3)+=ScaleFactor*(clhs100 + clhs231*clhs239 - clhs232*clhs238);
            rLocalLHS(10,4)+=ScaleFactor*(clhs119 + clhs231*clhs240 - clhs232*clhs241);
            rLocalLHS(10,5)+=ScaleFactor*(clhs139 + clhs231*clhs243 - clhs232*clhs242);
            rLocalLHS(10,6)+=ScaleFactor*(clhs158 + clhs231*clhs244 - clhs232*clhs245);
